        /// The colour a state's dot and its glow are filled with; anything unknown is idle grey.
        internal static Color StatusFill(string state)
        {
            if (state == "monitoring" || state == "waiting" || state == "checking" || state == "recovering") return Active;
            if (state == "attention") return Attention;
            if (state == "failed") return Danger;
            if (state == "paused") return Paused;
            return Idle;
        }

        /// The same dot in High Contrast: a system colour, and never a glow.
        internal static Color StatusSystem(string state)
        {
            if (state == "monitoring" || state == "waiting" || state == "checking" || state == "recovering") return SystemColors.Highlight;
            if (state == "attention" || state == "failed") return SystemColors.WindowText;
            return SystemColors.GrayText;
        }

        /// The glow around the status dot for one frame, or false when the state has none.
        /// brand.glow() in C#: `arc` is the checking arc's start angle in degrees, or -1, and a
        /// negative or NaN sinceEnteredMs means the state's one pulse is over. The caller draws
        /// no glow in High Contrast.
        internal static bool Glow(string state, double elapsedMs, double sinceEnteredMs, bool reduced,
                                  out double opacity, out double scale, out double arc)
        {
            opacity = 0;
            scale = 1;
            arc = -1;
            if (state == "monitoring")
                return Breathe(elapsedMs, reduced, GlowMonitoringMs, GlowMonitoringLow, GlowMonitoringHigh,
                               GlowMonitoringScaleLow, GlowMonitoringScaleHigh, out opacity, out scale);
            if (state == "recovering")
                return Breathe(elapsedMs, reduced, GlowRecoveringMs, GlowRecoveringLow, GlowRecoveringHigh,
                               GlowRecoveringScaleLow, GlowRecoveringScaleHigh, out opacity, out scale);
            if (state == "waiting")
            {
                opacity = GlowStill;
                return true;
            }
            if (state == "checking")
            {
                opacity = GlowStill;
                arc = reduced ? GlowArcStillAt : elapsedMs % GlowArcMs / GlowArcMs * 360.0;
                return true;
            }
            if (state == "attention" || state == "failed")
            {
                opacity = GlowStill;
                if (!reduced && sinceEnteredMs >= 0 && sinceEnteredMs < GlowAttentionMs)
                    opacity = GlowStill + (GlowAttentionPeak - GlowStill) * Breath(sinceEnteredMs, GlowAttentionMs);
                return true;
            }
            return false;
        }

        /// Whether a frame timer has anything to draw for this state.
        internal static bool GlowMoves(string state, double sinceEnteredMs, bool reduced)
        {
            if (reduced) return false;
            if (state == "monitoring" || state == "recovering" || state == "checking") return true;
            return (state == "attention" || state == "failed") && sinceEnteredMs >= 0 && sinceEnteredMs < GlowAttentionMs;
        }

        private static bool Breathe(double elapsedMs, bool reduced, double cycleMs, double low, double high,
                                    double small, double large, out double opacity, out double scale)
        {
            if (reduced)
            {
                opacity = (low + high) / 2;
                scale = 1;
                return true;
            }
            double wave = Breath(elapsedMs, cycleMs);
            opacity = low + (high - low) * wave;
            scale = small + (large - small) * wave;
            return true;
        }

        /// 0 at the start of a cycle, 1 halfway, 0 again: a raised cosine.
        private static double Breath(double elapsedMs, double cycleMs)
        {
            return 0.5 - 0.5 * Math.Cos(2 * Math.PI * (elapsedMs % cycleMs) / cycleMs);
        }

        /// How far a transition has come, 0 to 1, after `progress` of TransitionMs: brand.ease(), the
        /// CSS cubic-bezier TransitionEaseX1, Y1, X2, Y2. Held at 0 before the start and 1 after the end.
        internal static double Ease(double progress)
        {
            if (!(progress > 0)) return 0;
            if (progress >= 1) return 1;
            double t = progress;
            for (int i = 0; i < 8; i++)
            {
                double error = Bezier(TransitionEaseX1, TransitionEaseX2, t) - progress;
                if (Math.Abs(error) < 1e-7) return Bezier(TransitionEaseY1, TransitionEaseY2, t);
                double slope = BezierSlope(TransitionEaseX1, TransitionEaseX2, t);
                if (Math.Abs(slope) < 1e-6) break;
                t = Math.Min(1.0, Math.Max(0.0, t - error / slope));
            }
            double low = 0, high = 1;
            t = progress;
            for (int i = 0; i < 40; i++)
            {
                double value = Bezier(TransitionEaseX1, TransitionEaseX2, t);
                if (Math.Abs(value - progress) < 1e-7) break;
                if (value < progress) low = t; else high = t;
                t = (low + high) / 2.0;
            }
            return Bezier(TransitionEaseY1, TransitionEaseY2, t);
        }

        private static double Bezier(double a, double b, double t)
        {
            return ((1.0 - 3.0 * b + 3.0 * a) * t + (3.0 * b - 6.0 * a)) * t * t + 3.0 * a * t;
        }

        private static double BezierSlope(double a, double b, double t)
        {
            return 3.0 * (1.0 - 3.0 * b + 3.0 * a) * t * t + 2.0 * (3.0 * b - 6.0 * a) * t + 3.0 * a;
        }

        /// The check box's fill (brand.CHECKBOX): the well unchecked, the accent checked, the surface
        /// when disabled. `on` is checked; draw the inset elevation inside the border when CheckWell.
        internal static Color CheckFill(bool on, bool enabled)
        {
            if (!on && enabled) return Inset;
            if (on && enabled) return Accent;
            return Surface;
        }

        /// The check box's hairline edge: muted unchecked, where nothing inside says it is a box.
        internal static Color CheckEdge(bool on, bool enabled)
        {
            if (!on && enabled) return Muted;
            if (on && enabled) return Accent;
            return Line;
        }

        /// The check mark's colour, or false when the box has no mark.
        internal static bool CheckMark(bool on, bool enabled, out Color mark)
        {
            mark = Color.Empty;
            if (on && enabled) { mark = OnAccent; return true; }
            if (on && !enabled) { mark = Muted; return true; }
            return false;
        }

        /// How many shadows an elevation recipe ("card", "control" or "inset") has; 0 for any other.
        internal static int ElevationCount(string recipe)
        {
            if (recipe == "card") return 2;
            if (recipe == "control") return 2;
            if (recipe == "inset") return 2;
            return 0;
        }

        /// Shadow `index` of an elevation recipe (brand.SHADOWS), front to back as the panel's
        /// stylesheet lists them, so paint from the last to the first. In CSS px: the offset, the
        /// blur (a Gaussian with sigma blur / 2), the alpha, whether it falls inside the box rather
        /// than around it, and its colour. False past the last shadow.
        internal static bool ElevationShadow(string recipe, int index, out double dx, out double dy,
                                             out double blur, out double alpha, out bool inset, out Color tone)
        {
            dx = 0;
            dy = 0;
            blur = 0;
            alpha = 0;
            inset = false;
            tone = Color.Empty;
            if (recipe == "card")
            {
                if (index == 0) { dx = 4; dy = 4; blur = 14; alpha = 0.55; tone = ShadowDark; return true; }
                if (index == 1) { dx = -4; dy = -4; blur = 14; alpha = 0.9; tone = ShadowLight; return true; }
                return false;
            }
            if (recipe == "control")
            {
                if (index == 0) { dx = 2; dy = 2; blur = 6; alpha = 0.45; tone = ShadowDark; return true; }
                if (index == 1) { dx = -2; dy = -2; blur = 6; alpha = 0.9; tone = ShadowLight; return true; }
                return false;
            }
            if (recipe == "inset")
            {
                if (index == 0) { dx = 2; dy = 2; blur = 6; alpha = 0.38; inset = true; tone = ShadowDark; return true; }
                if (index == 1) { dx = -2; dy = -2; blur = 6; alpha = 0.5; inset = true; tone = ShadowLight; return true; }
                return false;
            }
            return false;
        }

        /// Whether the check box draws the inset elevation inside its border, in either theme.
        /// Never in High Contrast.
        internal static bool CheckWell(bool on, bool enabled)
        {
            return !on && enabled;
        }

        /// The check box in High Contrast (brand.CHECKBOX_SYSTEM): system colours, and no shadow.
        internal static Color CheckSystemFill(bool on, bool enabled)
        {
            if (on && enabled) return SystemColors.Highlight;
            return SystemColors.Window;
        }

        internal static Color CheckSystemEdge(bool on, bool enabled)
        {
            if (!on && enabled) return SystemColors.WindowText;
            if (on && enabled) return SystemColors.Highlight;
            return SystemColors.GrayText;
        }

        internal static bool CheckSystemMark(bool on, bool enabled, out Color mark)
        {
            mark = Color.Empty;
            if (on && enabled) { mark = SystemColors.HighlightText; return true; }
            if (on && !enabled) { mark = SystemColors.GrayText; return true; }
            return false;
        }

