            internal const int ElevInsetReachRight = 0;
            internal const int ElevInsetReachBottom = 0;

            /// The colour a state's dot and its glow are filled with; anything unknown is idle grey.
            internal static Color StatusFill(string state)
            {
                if (state == "monitoring" || state == "waiting" || state == "checking" || state == "recovering") return Active;
                if (state == "attention") return Attention;
                if (state == "failed") return Danger;
                if (state == "paused") return Paused;
                return Idle;
            }

            /// The check box's fill (brand.CHECKBOX): the well unchecked, the accent checked, the surface
            /// when disabled. `on` is checked; draw the inset elevation inside the border when CheckWell.
            internal static Color CheckFill(bool on, bool enabled)
            {
                if (!on && enabled) return Inset;
                if (on && enabled) return Accent;
                return Surface;
            }

            /// The check box's hairline edge: muted unchecked, where nothing inside says it is a box.
            internal static Color CheckEdge(bool on, bool enabled)
            {
                if (!on && enabled) return Muted;
                if (on && enabled) return Accent;
                return Line;
            }

            /// The check mark's colour, or false when the box has no mark.
            internal static bool CheckMark(bool on, bool enabled, out Color mark)
            {
                mark = Color.Empty;
                if (on && enabled) { mark = OnAccent; return true; }
                if (on && !enabled) { mark = Muted; return true; }
                return false;
            }

            /// How many shadows an elevation recipe ("card", "control" or "inset") has; 0 for any other.
            internal static int ElevationCount(string recipe)
            {
                if (recipe == "card") return 3;
                if (recipe == "control") return 1;
                if (recipe == "inset") return 1;
                return 0;
            }

            /// Shadow `index` of an elevation recipe (brand.SHADOWS), front to back as the panel's
            /// stylesheet lists them, so paint from the last to the first. In CSS px: the offset, the
            /// blur (a Gaussian with sigma blur / 2), the alpha, whether it falls inside the box rather
            /// than around it, and its colour. False past the last shadow.
            internal static bool ElevationShadow(string recipe, int index, out double dx, out double dy,
                                                 out double blur, out double alpha, out bool inset, out Color tone)
            {
                dx = 0;
                dy = 0;
                blur = 0;
                alpha = 0;
                inset = false;
                tone = Color.Empty;
                if (recipe == "card")
                {
                    if (index == 0) { dx = 0; dy = 1; blur = 2; alpha = 0.7; tone = ShadowDark; return true; }
                    if (index == 1) { dx = 0; dy = 6; blur = 18; alpha = 0.35; tone = ShadowDark; return true; }
                    if (index == 2) { dx = 0; dy = 1; blur = 0; alpha = 0.45; inset = true; tone = ShadowLight; return true; }
                    return false;
                }
                if (recipe == "control")
                {
                    if (index == 0) { dx = 0; dy = 1; blur = 2; alpha = 0.6; tone = ShadowDark; return true; }
                    return false;
                }
                if (recipe == "inset")
                {
                    if (index == 0) { dx = 0; dy = 1; blur = 2; alpha = 0.55; inset = true; tone = ShadowDark; return true; }
                    return false;
                }
                return false;
            }
        }

        /// The notification-area icon's motion on the window's taskbar button (v0.6.5), from
        /// codex_auto_resume.tray: the icon's five states and the one each status light is drawn as, its
        /// rhythms, and its frames at every size the window's big icon has. TaskbarMark shows them.
        internal static class Mark
        {
            // tray.ICON_MOTION. The icon also reads four of brand.GLOW's rhythms, which Brand declares:
            // GlowMonitoringMs and GlowRecoveringMs (the breaths), GlowArcMs (recovering's turn) and
            // GlowAttentionMs (a problem's one pulse).
            internal const double TurnEveryMs = 30000;
            internal const double TurnMs = 2400;
            internal const int BreatheFrameMs = 300;
            internal const int TurnFrameMs = 200;
            internal const int Positions = 24;
            internal const int Levels = 9;
            internal const double Dim = 0.6;
            // A pixel's samples: brand.ICON_SUPERSAMPLE squared.
            internal const int Samples = 16;
            // What a head pixel's entry in the frames starts with (build/make_brand.py, mark_frames).
            internal const int EntryGround = 0;
            internal const int EntryHead = 1;
            internal const int EntrySamples = 2;

            /// The icon's state for the state a status light shows (tray.ICON_FOR_LIGHT); anything
            /// unknown is idle.
            internal static string IconState(string light)
            {
                if (light == "monitoring" || light == "waiting" || light == "checking") return "watching";
                if (light == "recovering") return "recovering";
                if (light == "attention") return "attention";
                if (light == "failed") return "failed";
                return "idle";
            }

            /// The head's full colour in an icon state (tray.icon_head_colour); anything unknown is idle's.
            internal static Color HeadColour(string state)
            {
                if (state == "watching" || state == "recovering") return Color.FromArgb(0x4F, 0xE0, 0xF5);
                if (state == "attention") return Color.FromArgb(0xE0, 0x9B, 0x57);
                if (state == "failed") return Color.FromArgb(0xF2, 0x87, 0x7C);
                return Color.FromArgb(0x94, 0xA3, 0xB8);
            }

            /// The head's colour at breathing `level` (tray.icon_level_colour): the top level is `colour`, the
            /// lowest Dim of the way toward the badge's deep blue.
            internal static Color LevelColour(Color colour, int level)
            {
                int top = Levels - 1;
                level = Math.Max(0, Math.Min(top, level));
                double amount = Dim * (top - level) / (double)top;
                return Color.FromArgb(Toward(colour.R, 0x0B, amount), Toward(colour.G, 0x25, amount),
                                      Toward(colour.B, 0x45, amount));
            }

            private static int Toward(int one, int other, double amount)
            {
                return (int)Math.Floor(one + (other - one) * amount + 0.5);
            }

            /// How far round the ring the head has travelled, in degrees, or -1 at rest (tray.icon_turn):
            /// watching once in the last TurnMs of every TurnEveryMs, eased in and out; recovering all the
            /// time, once per GlowArcMs.
            internal static double Turn(string state, double elapsedMs)
            {
                if (state == "recovering") return 360.0 * (elapsedMs % GlowArcMs) / GlowArcMs;
                if (state == "watching")
                {
                    double into = elapsedMs % TurnEveryMs - (TurnEveryMs - TurnMs);
                    if (into < 0) return -1;
                    return 360.0 * (0.5 - 0.5 * Math.Cos(Math.PI * Math.Min(1.0, into / TurnMs)));
                }
                return -1;
            }

            /// One frame, as (position, level) (tray.icon_frame): position 0 is the head in its place, the
            /// top level its full colour. With motion reduced every state is at rest. A negative
            /// sinceEnteredMs means the state's one pulse is over.
            internal static void Frame(string state, double elapsedMs, double sinceEnteredMs, bool reduced,
                                       out int position, out int level)
            {
                position = 0;
                level = Levels - 1;
                if (reduced) return;
                double turn = Turn(state, elapsedMs);
                if (turn >= 0) position = (int)Math.Round(turn / (360.0 / Positions)) % Positions;
                if (state == "watching")
                {
                    level = BreathLevel(elapsedMs, GlowMonitoringMs);
                    return;
                }
                if (state == "recovering")
                {
                    level = BreathLevel(elapsedMs, GlowRecoveringMs);
                    return;
                }
                position = 0;
                if ((state == "attention" || state == "failed") && sinceEnteredMs >= 0 && sinceEnteredMs < GlowAttentionMs)
                    level = BreathLevel(sinceEnteredMs, GlowAttentionMs);
            }

            /// How soon the next frame is due, in ms, or -1 when nothing moves (tray.icon_frame_ms).
            internal static int FrameMs(string state, double elapsedMs, double sinceEnteredMs, bool reduced)
            {
                if (reduced) return -1;
                if (state == "recovering") return TurnFrameMs;
                if (state == "watching") return Turn(state, elapsedMs) >= 0 ? TurnFrameMs : BreatheFrameMs;
                if ((state == "attention" || state == "failed") && sinceEnteredMs >= 0 && sinceEnteredMs < GlowAttentionMs)
                    return BreatheFrameMs;
                return -1;
            }

            /// Full colour at the start of a cycle, dimmest halfway, full again (tray._breath_level).
            private static int BreathLevel(double elapsedMs, double cycleMs)
            {
                return (int)Math.Round((Levels - 1) * (1.0 - Breath(elapsedMs, cycleMs)));
            }

            /// The frames for a big icon of `size` px, base64 (build/make_brand.py, mark_frames), or null
            /// for a size there are none of.
            internal static string Frames(int size)
            {
                if (size == 32) return Frames32;
                if (size == 40) return Frames40;
                if (size == 48) return Frames48;
                if (size == 56) return Frames56;
                if (size == 64) return Frames64;
                return null;
            }

